"""Reference model of /workspace/PROTOCOL.md, pure Python (development only)."""
import struct, zlib, hashlib, sys, os
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'project'))
from wire import packet, payload as gen_payload, emissions, NAMES

MASK24 = (1 << 24) - 1
MASK32 = (1 << 32) - 1
M64 = (1 << 64) - 1

def ip_cksum(data):
    total = 0
    for i in range(0, len(data) - 1, 2):
        total += (data[i] << 8) | data[i + 1]
    if len(data) % 2:
        total += data[-1] << 8
    while total >> 16:
        total = (total & 0xffff) + (total >> 16)
    return (~total) & 0xffff

def icrc(frame):
    # frame without trailing ICRC is frame[:-4]; frame includes 4 trailing bytes placeholder
    ip = frame[14:]
    ip_len = (ip[2] << 8) | ip[3]
    crc = bytearray(b'\xff' * 8 + bytes(ip[:ip_len - 4]))
    crc[9] = 255; crc[16] = 255; crc[18] = 255; crc[19] = 255
    crc[34] = 255; crc[35] = 255; crc[40] = 255
    return zlib.crc32(bytes(crc)) & MASK32

def validate_ingress(rank, frame, D):
    """returns (wire_ok, parsed) ; parsed = dict(kind,p|prefix_len,payload)"""
    flen = len(frame)
    if flen < 14 + 20 + 8 + 12 + 4:
        return False, None
    if (frame[12] << 8) | frame[13] != 0x0800:
        return False, None
    ip = frame[14:]
    if ip[0] != 0x45:
        return False, None
    ip_len = (ip[2] << 8) | ip[3]
    if 14 + ip_len != flen:
        return False, None
    if ip[9] != 17:
        return False, None
    if ip_len < 20 + 8 + 12 + 4:
        return False, None
    if ip[6] != 0 or ip[7] not in (0x00, 0x40):
        return False, None
    if (ip[10] << 8 | ip[11]) != ip_cksum(bytes(ip[:20])):
        return False, None
    udp = ip[20:]
    udp_len = (udp[4] << 8) | udp[5]
    if udp_len != ip_len - 20:
        return False, None
    if (udp[0] << 8 | udp[1]) != 4791 or (udp[2] << 8 | udp[3]) != 4791:
        return False, None
    if (udp[6] << 8 | udp[7]) != 0:
        return False, None
    if udp_len < 8 + 12 + 4:
        return False, None
    bth = udp[8:]
    opcode = bth[0]
    if opcode not in (0x04, 0x11):
        return False, None
    if bth[1] != 0:
        return False, None
    if (bth[2] << 8 | bth[3]) != 0xffff:
        return False, None
    qpn = (bth[4] << 24) | (bth[5] << 16) | (bth[6] << 8) | bth[7]
    if (qpn >> 24) & 0xff:
        return False, None
    apsn = (bth[8] << 24) | (bth[9] << 16) | (bth[10] << 8) | bth[11]
    psn = apsn & MASK24
    if opcode == 0x04 and (apsn >> 24) != 0x80:
        return False, None
    if opcode == 0x11 and (apsn >> 24) != 0x00:
        return False, None
    body = bth[12:]
    pay_len = udp_len - 8 - 12 - 4
    if opcode == 0x11:
        if pay_len != 4:
            return False, None
        aeth = (body[0] << 24) | (body[1] << 16) | (body[2] << 8) | body[3]
        if (aeth >> 24) != 0x1f:
            return False, None
        if aeth & MASK24 != (psn + 1) & MASK24:
            return False, None
    else:
        if pay_len != 4 * D:
            return False, None
    got = (frame[-4] | (frame[-3] << 8) | (frame[-2] << 16) | (frame[-1] << 24))
    if got != icrc(frame):
        return False, None
    return True, dict(opcode=opcode, qpn=qpn & MASK24, psn=psn, payload=bytes(body[:pay_len]) if opcode == 4 else b'')

def ordinal_excluding(excl, rank):
    return rank - (1 if rank > excl else 0)

def rank_from_ordinal(excl, o):
    n = 0
    for r in range(4):
        if r == excl:
            continue
        if n == o:
            return r
        n += 1
    raise AssertionError

class Collector:
    def __init__(self, case, emit):
        self.kind = case['primitive']; self.mode = case['mode']; self.root = case['root']
        self.K = case['segments']; self.D = case['words']; self.N = case['capacity']
        self.start = case['start']
        self.emit = emit
        self.b = 0
        self.slots = {}      # p -> {'mask':int,'agg':[..],'raw':bytes,'raws':{}}
        self.R = [0, 0, 0, 0]
        self.sent = [0, 0, 0, 0]
        self.ack = [0, 0, 0, 0]
        self.U = [0, 0, 0, 0]
        self.repeat = [False] * 4
        self.c = dict(data_ok=0, ack_ok=0, tx_data=0, tx_ack=0, accepted=0, dup=0,
                      blocked=0, stale=0, wire_bad=0, ep_bad=0, ign=0, fail=0)
        # output space
        K = self.K
        if self.kind in ('allreduce',): self.outc = [K] * 4
        elif self.kind == 'reduce': self.outc = [K if r == self.root else 0 for r in range(4)]
        elif self.kind == 'broadcast': self.outc = [0 if r == self.root else K for r in range(4)]
        elif self.kind == 'barrier': self.outc = [1] * 4
        elif self.kind == 'allgather': self.outc = [3 * K] * 4
        else: self.outc = [K // 4] * 4

    def required_sources(self, rank):
        if self.kind == 'broadcast':
            return rank == self.root
        return True

    def record(self, d, q):
        """returns (p, src) for output record q of receiver d, or None"""
        K = self.K
        if self.kind in ('allreduce', 'reduce', 'broadcast'):
            return (q, -1)
        if self.kind == 'barrier':
            return (0, -1)
        if self.kind == 'allgather':
            return (q // 3, rank_from_ordinal(d, q % 3))
        if self.kind == 'reducescatter':
            m = K // 4
            return (d * m + q, -1)
        raise AssertionError

    def complete(self, p):
        s = self.slots.get(p)
        if s is None:
            return False
        if self.kind == 'broadcast':
            return True  # only root accepted, allocation implies complete
        return s['mask'] == 0xf

    def ready(self, d, q):
        if q >= self.outc[d]:
            return False
        p, src = self.record(d, q)
        return self.complete(p)

    # ---------- emission ----------
    def send_ack(self, r, prefix):
        psn = (self.start + prefix - 1) & MASK24
        f = packet(r, psn, ack=True, outgoing=True)
        if self.emit(r, f):
            self.c['tx_ack'] += 1
            return True
        self.c['fail'] += 1
        return False

    def result_frame(self, d, q):
        p, src = self.record(d, q)
        s = self.slots[p]
        if self.kind == 'barrier':
            body = b''
        elif self.kind == 'broadcast':
            body = s['raw']
        elif self.kind == 'allgather':
            body = s['raws'][src]
        else:
            body = struct.pack('!%dI' % self.D, *s['agg'])
        psn = (self.start + q) & MASK24
        return packet(d, psn, body, outgoing=True)

    def eligible(self, r):
        R = self.R[r]
        if self.mode == 3:
            return R
        ack = self.ack
        K = self.K
        if self.kind in ('allreduce', 'barrier'):
            return min(R, ack[r])
        if self.kind == 'reduce':
            return min(R, ack[self.root])
        if self.kind == 'broadcast':
            if r != self.root:
                return 0
            return min([R] + [ack[d] for d in range(4) if d != self.root])
        if self.kind == 'reducescatter':
            m = K // 4
            g = 0
            for d in range(4):
                t = min(m, max(0, ack[d] - d * m))
                g += t
                if t < m:
                    break
            return min(R, g)
        if self.kind == 'allgather':
            v = R
            for d in range(4):
                if d == r:
                    continue
                o = ordinal_excluding(d, r)
                v = min(v, max(0, (ack[d] - o + 2) // 3))
            return v
        raise AssertionError

    def service(self, retry_rank=-1):
        ok = True
        for r in range(4):
            e = self.eligible(r)
            if (e > self.U[r] or self.repeat[r]) and e > 0:
                if self.send_ack(r, e):
                    self.U[r] = e
                    self.repeat[r] = False
                else:
                    ok = False; break
        if ok and retry_rank >= 0:
            d = retry_rank
            for q in range(self.ack[d], self.sent[d]):
                f = self.result_frame(d, q)
                if self.emit(d, f):
                    self.c['tx_data'] += 1
                else:
                    self.c['fail'] += 1; ok = False; break
        if ok:
            for d in range(4):
                while self.ready(d, self.sent[d]):
                    f = self.result_frame(d, self.sent[d])
                    if self.emit(d, f):
                        self.c['tx_data'] += 1
                        self.sent[d] += 1
                    else:
                        self.c['fail'] += 1; ok = False; break
                if not ok:
                    break
        self.retire()
        return ok

    def retire(self):
        K = self.K
        while self.b < K:
            p = self.b
            if not self.complete(p):
                break
            if self.kind == 'allgather':
                if min(self.ack) < 3 * p + 3:
                    break
            elif self.kind == 'reducescatter':
                m = K // 4
                d = p // m
                if self.ack[d] < p + 1:
                    break
            elif self.kind in ('reduce',):
                if self.ack[self.root] < p + 1:
                    break
            elif self.kind == 'broadcast':
                if any(self.ack[d] < p + 1 for d in range(4) if d != self.root):
                    break
            elif self.kind == 'allreduce':
                if min(self.ack) < p + 1:
                    break
            elif self.kind == 'barrier':
                if min(self.ack) < 1:
                    break
            srcs = [self.root] if self.kind == 'broadcast' else range(4)
            if any(self.U[r] <= p for r in srcs):
                break
            self.slots.pop(p, None)
            self.b = p + 1

    # ---------- ingress ----------
    def ingress(self, rank, frame):
        ok, parsed = validate_ingress(rank, frame, self.D)
        if not ok:
            self.c['wire_bad'] += 1
            return
        hostmac = bytes((2, 0, 0, 0, 0, rank + 1)); swmac = bytes((2, 1, 0, 0, 0, rank + 1))
        if frame[0:6] != swmac or frame[6:12] != hostmac:
            self.c['ep_bad'] += 1; return
        hip = bytes((10, 0, 0, rank + 1)); sip = bytes((10, 0, 0, 101 + rank))
        if frame[26:30] != sip or frame[30:34] != hip:
            self.c['ep_bad'] += 1; return
        if parsed['qpn'] != 0x200 + rank:
            self.c['ep_bad'] += 1; return
        if parsed['opcode'] == 0x11:
            self.c['ack_ok'] += 1
            n = (parsed['psn'] - self.start + 1) & MASK24
            if n > self.ack[rank] and n <= self.sent[rank]:
                self.ack[rank] = n
            else:
                self.c['ign'] += 1
            self.service()
            return
        if not self.required_source_rank(rank):
            self.c['ep_bad'] += 1; return
        self.c['data_ok'] += 1
        p = (parsed['psn'] - self.start) & MASK24
        if p >= self.K:
            self.c['ep_bad'] += 1; self.c['data_ok'] -= 1
            return
        b = self.b
        if p < b:
            self.c['stale'] += 1; self.repeat[rank] = True; self.service(); return
        if p >= min(self.K, b + self.N):
            self.c['blocked'] += 1; self.service(); return
        s = self.slots.get(p)
        bit = 1 << rank
        if s is None:
            s = self.new_slot(p); self.slots[p] = s
        if s['mask'] & bit:
            self.c['dup'] += 1; self.repeat[rank] = True; self.service(); return
        self.accept(s, rank, parsed['payload'])
        self.c['accepted'] += 1
        s['mask'] |= bit
        self.advance_R(rank)
        self.service()

    def required_source_rank(self, rank):
        if self.kind == 'broadcast' and rank != self.root:
            return False
        return True

    def new_slot(self, p):
        return dict(mask=0, agg=[0] * self.D, raw=b'', raws={})

    def accept(self, s, rank, body):
        if self.kind in ('broadcast', 'allgather'):
            if self.kind == 'broadcast':
                s['raw'] = body
            else:
                s['raws'][rank] = body
        elif self.kind == 'barrier':
            pass
        else:
            words = struct.unpack('!%dI' % self.D, body) if self.D else ()
            if s['mask'] == 0:
                s['agg'] = list(words)
            else:
                s['agg'] = [(a + w) & MASK32 for a, w in zip(s['agg'], words)]

    def advance_R(self, rank):
        if self.kind == 'broadcast' and rank != self.root:
            return
        while self.R[rank] < self.K and self.R[rank] in self.slots and \
                (self.slots[self.R[rank]]['mask'] & (1 << rank) or
                 (self.kind == 'broadcast' and self.R[rank] in self.slots)):
            self.R[rank] += 1

    def retry(self, rank):
        self.service(retry_rank=rank)

    def state(self):
        return [self.b, len(self.slots)] + self.R + self.sent + self.ack + self.U + \
            [self.c['data_ok'], self.c['ack_ok'], self.c['tx_data'], self.c['tx_ack'],
             self.c['accepted'], self.c['dup'], self.c['blocked'], self.c['stale'],
             self.c['wire_bad'], self.c['ep_bad'], self.c['ign'], self.c['fail'], 0, 0]

    def digest(self):
        h = 14695981039346656037
        for p in sorted(self.slots):
            s = self.slots[p]
            comp = 1 if self.complete(p) else 0
            for b in struct.pack('<Q', p):
                h = ((h ^ b) * 1099511628211) & M64
            h = ((h ^ s['mask']) * 1099511628211) & M64
            h = ((h ^ comp) * 1099511628211) & M64
            if self.kind == 'allgather':
                for r in range(4):
                    present = 1 if (s['mask'] >> r) & 1 else 0
                    h = ((h ^ present) * 1099511628211) & M64
                    if present:
                        for b in s['raws'][r]:
                            h = ((h ^ b) * 1099511628211) & M64
            elif self.kind == 'broadcast':
                for b in s['raw']:
                    h = ((h ^ b) * 1099511628211) & M64
            elif self.kind == 'barrier':
                pass
            else:
                for w in s['agg']:
                    for b in struct.pack('<I', w):
                        h = ((h ^ b) * 1099511628211) & M64
        return format(h, '016x')

def run_case(case):
    tape = hashlib.sha256()
    st = dict(packets=0, bytes=0, budget=-1, trace=[], snaps=[], limit=case.get('trace', 0))
    def emit(rank, frame):
        if st['budget'] == 0:
            return False
        if st['budget'] > 0:
            st['budget'] -= 1
        tape.update(bytes((rank,)) + struct.pack('<I', len(frame)) + frame)
        st['packets'] += 1; st['bytes'] += len(frame)
        if len(st['trace']) < st['limit']:
            st['trace'].append({'rank': rank, 'hex': frame.hex()})
        return True
    col = Collector(case, emit)
    for name, arg, frame in emissions(case):
        if name == 'wire':
            col.ingress(arg, frame)
        elif name == 'flush':
            col.service()
        elif name == 'retry':
            col.retry(arg)
        elif name == 'budget':
            st['budget'] = arg
        elif name == 'snap':
            st['snaps'].append({'tag': arg, 'state': col.state(), 'buffer': col.digest(),
                                'wire_sha256': tape.hexdigest(), 'packets': st['packets'], 'bytes': st['bytes']})
        else:
            raise ValueError(name)
    return {'state': col.state(), 'buffer': col.digest(), 'wire_sha256': tape.hexdigest(),
            'packets': st['packets'], 'bytes': st['bytes'], 'snapshots': st['snaps'], 'trace': st['trace']}

def solve(req):
    return {'cases': [run_case(c) for c in req['cases']]}

